/**
 * Centralized TypeScript type definitions for the AI Researcher Finder application
 *
 * This file serves as the single source of truth for all shared types across the application.
 * Types are organized by their domain and purpose.
 */

// ============================================================================
// CORE SEARCH TYPES
// ============================================================================

/**
 * Represents a search strategy generated by AI to find relevant researchers
 */
export interface SearchStrategy {
  name: string;
  rationale: string;
  queries: string[];
}

/**
 * Represents a research area with its importance level
 */
export interface ResearchArea {
  term: string;
  importance: 'high' | 'medium' | 'low';
}

/**
 * Information about which search strategies were used and their results
 */
export interface StrategyUsed {
  name: string;
  rationale: string;
  papersFound: number;
}

// ============================================================================
// PAPER TYPES
// ============================================================================

/**
 * Represents a paper from arXiv with its metadata
 */
export interface ArxivPaper {
  id: string;
  title: string;
  authors: string[];
  summary: string;
  published: string;
  link: string;
}

/**
 * An arXiv paper extended with its embedding vector and optional similarity score
 */
export interface PaperWithEmbedding extends ArxivPaper {
  embedding: number[];
  similarityScore?: number;
}

// ============================================================================
// LOCATION TYPES
// ============================================================================

/**
 * Possible locations for a researcher
 */
export type Location = 'USA' | 'International' | 'Unknown';

// ============================================================================
// RESEARCHER/AUTHOR TYPES
// ============================================================================

/**
 * Represents an author candidate with their most relevant paper
 */
export interface AuthorCandidate {
  name: string;
  paper: ArxivPaper;
  similarityScore: number;
  location?: Location;
  affiliation?: string;
}

/**
 * A top researcher with AI-generated fit analysis
 */
export interface TopResearcher extends AuthorCandidate {
  aiRelevanceScore: number;
  fitReason: string;
}

/**
 * An additional candidate without AI analysis (for cost optimization)
 */
export interface AdditionalCandidate {
  name: string;
  similarityScore: number;
  location: Location;
  affiliation?: string;
  paper: ArxivPaper;
}

// ============================================================================
// API RESPONSE TYPES
// ============================================================================

/**
 * Statistics about similarity scores
 */
export interface SimilarityStats {
  min: number;
  max: number;
  avg: number;
  median: number;
}

/**
 * Debug information about similarity scoring
 */
export interface SimilarityDebug {
  stats: SimilarityStats;
  topPapers: { title: string; score: number; }[];
}

/**
 * Top researcher in API response format (with guaranteed location field)
 */
export interface TopResearcherResponse {
  name: string;
  similarityScore: number;
  aiRelevanceScore: number;
  fitReason: string;
  location: Location;
  affiliation?: string;
  paper: ArxivPaper;
}

/**
 * Additional candidate in API response format (with guaranteed location field)
 */
export interface AdditionalCandidateResponse {
  name: string;
  similarityScore: number;
  location: Location;
  affiliation?: string;
  paper: ArxivPaper;
}

/**
 * Complete API response from the find-researchers endpoint
 */
export interface ApiResponse {
  searchStrategies: SearchStrategy[];
  strategiesUsed?: StrategyUsed[];
  topResearchers: TopResearcherResponse[];
  additionalCandidates: AdditionalCandidateResponse[];
  totalPapersAnalyzed: number;
  similarityDebug?: SimilarityDebug;
  debug?: string[];
  error?: string;
}
